import 'package:flutter/material.dart';
import '../../../services/personal_ai/supplier_finder_service.dart';
import '../../messenger/presentation/messenger_screen.dart';
class AurenSupplierFinderScreen extends StatefulWidget{const AurenSupplierFinderScreen({super.key});@override State<AurenSupplierFinderScreen> createState()=>_AurenSupplierFinderScreenState();}
class _AurenSupplierFinderScreenState extends State<AurenSupplierFinderScreen>{final _q=TextEditingController();String _cat='All',_currency='';List<SupplierMatch>? _results;bool _loading=false;
Future<void> _find()async{if(_q.text.trim().isEmpty)return;setState(()=>_loading=true);try{final r=await SupplierFinderService().find(query:_q.text,category:_cat,currency:_currency);if(mounted)setState(()=>_results=r);}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('تعذر البحث عن الموردين: $e')));}finally{if(mounted)setState(()=>_loading=false);}}
@override void dispose(){_q.dispose();super.dispose();}
@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('Supplier Finder')),body:ListView(padding:const EdgeInsets.all(18),children:[const Text('Supplier Finder',style:TextStyle(fontSize:26,fontWeight:FontWeight.bold)),const SizedBox(height:6),const Text('ابحث عن موردين ومنتجات وخدمات موجودة في Marketplace، مع توضيح سبب المطابقة.'),const SizedBox(height:14),TextField(controller:_q,onSubmitted:(_)=>_find(),decoration:const InputDecoration(labelText:'ماذا تريد أن تشتري أو توفر؟',prefixIcon:Icon(Icons.search),border:OutlineInputBorder())),const SizedBox(height:10),Row(children:[Expanded(child:DropdownButtonFormField<String>(value:_cat,items:const ['All','General','Fashion','Food','Electronics','Services','Home','Agriculture','Other'].map((x)=>DropdownMenuItem(value:x,child:Text(x))).toList(),onChanged:(v)=>setState(()=>_cat=v??'All'),decoration:const InputDecoration(labelText:'الفئة'))),const SizedBox(width:10),Expanded(child:DropdownButtonFormField<String>(value:_currency.isEmpty?null:_currency,items:const [DropdownMenuItem(value:'USD',child:Text('USD')),DropdownMenuItem(value:'SDG',child:Text('SDG')),DropdownMenuItem(value:'AED',child:Text('AED')),DropdownMenuItem(value:'SAR',child:Text('SAR')),DropdownMenuItem(value:'EUR',child:Text('EUR'))],onChanged:(v)=>setState(()=>_currency=v??''),decoration:const InputDecoration(labelText:'العملة')))]),const SizedBox(height:12),FilledButton.icon(onPressed:_loading?null:_find,icon:const Icon(Icons.travel_explore),label:Text(_loading?'جاري البحث…':'ابحث عن الموردين')),if(_results!=null)...[_results!.isEmpty?const Padding(padding:EdgeInsets.all(24),child:Text('لم نجد مطابقة حالية. جرّب وصفًا مختلفًا أو اطلب من AUREN إنشاء طلب توريد.')):..._results!.map((m)=>Card(child:ListTile(title:Text(m.product.name),subtitle:Text('${m.product.priceMinor/100} ${m.product.currency} • ${m.reasons.join(' • ')}'),trailing:CircleAvatar(child:Text('${m.score}')),onTap:()=>Navigator.push(c,MaterialPageRoute(builder:(_)=>MessengerScreen(initialPrompt:'أريد التواصل مع صاحب المنتج ${m.product.name} كمورد محتمل. حلّل لي المنتج والسعر والملاءمة، ولا ترسل أي رسالة بدون موافقتي.')))))] ]));}